// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // A non-owner sends 1 wei to the contract via fallback
        address nonOwner = address(0x1234);
        vm.deal(nonOwner, 1 wei);
        vm.prank(nonOwner);
        (bool ok,) = address(c).call{value: 1 wei}("");
        require(ok, "fallback call failed");

        // Owner tries to withdraw all balance
        address payable owner = payable(c.owner());
        uint256 balanceBefore = address(c).balance;
        vm.prank(owner);
        // withdrawAll will call onlyOwner; in reference it works, in bug it reverts
        // We need to catch possible revert:
        bool success;
        try c.withdrawAll() {
            success = true;
        } catch {
            success = false;
        }
        // Reference: success is true, balance becomes 0;
        // Bug: success is false, balance stays > 0
        assertTrue(success && address(c).balance == 0);
    }
}

