import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address owner = address(this);
        uint initialBalance = owner.balance;

        // Owner deposits 1 ether via fallback
        vm.deal(owner, initialBalance + 1 ether);
        vm.prank(owner);
        (bool sent, ) = address(c).call{value: 1 ether}("");
        require(sent, "deposit failed");

        // Owner withdraws 1 ether
        vm.prank(owner);
        c.withdraw(1 ether);

        // Reference contract: owner balance = initialBalance + 1 - 1 = initialBalance
        // Buggy contract: withdraw sends 2 ether, reverts because contract only has 1 ether
        // So the call to withdraw reverts, and owner balance = initialBalance + 1
        uint finalBalance = owner.balance;
        assertEq(finalBalance, initialBalance);
    }
}

